import { BaseEntity } from '../../core/blocks/index.js';

/**
 * Artifact Entity - v24 Absolute Final
 * Storage reference for files generated by the system.
 */
export class Artifact extends BaseEntity {
  constructor(raw = {}) {
    super(raw);
    
    this.data = {
      ...this.data,
      type: raw.type || raw.data?.type || '',
      fileId: raw.fileId || raw.data?.fileId || null,
      mimeType: raw.mimeType || raw.data?.mimeType || '',
      metadata: raw.metadata || raw.data?.metadata || {}
    };
  }

  get name() { return this.identity.name || `Artifact ${this.id.substring(0, 8)}`; }

  toJSON() {
    return {
      ...super.toJSON(),
      type: this.data.type,
      fileId: this.data.fileId,
      mimeType: this.data.mimeType,
      metadata: this.data.metadata,
      url: this.data.fileId ? `/api/files/download/${this.data.fileId}` : null
    };
  }
}
